// Exposes the directory to in-browser AI agents via WebMCP
// (https://webmachinelearning.github.io/webmcp/). Reuses the llms.txt index and
// per-page Markdown generated by docusaurus-plugin-llms.
import ExecutionEnvironment from '@docusaurus/ExecutionEnvironment';

let llmsIndex;

async function loadIndex() {
  if (!llmsIndex) {
    llmsIndex = fetch('/llms.txt')
      .then((res) => res.text())
      .then((text) =>
        [...text.matchAll(/^- \[([^\]]+)\]\(([^)]+)\)(?::\s*(.*))?$/gm)].map(
          ([, title, url, description]) => ({title, url, description: description || ''}),
        ),
      );
  }
  return llmsIndex;
}

const asText = (value) => ({
  content: [{type: 'text', text: typeof value === 'string' ? value : JSON.stringify(value, null, 2)}],
});

const tools = [
  {
    name: 'search_crisis_resources',
    description:
      'Search the Canadian crisis resources directory (crisis lines, helplines, mental health services) by keyword, province, territory, or audience. Returns matching pages with Markdown URLs. In an emergency, direct the user to call 9-1-1 or call/text 9-8-8.',
    inputSchema: {
      type: 'object',
      properties: {
        query: {type: 'string', description: 'Keywords, e.g. "youth Ontario", "Indigenous", "Quebec suicide"'},
      },
      required: ['query'],
    },
    async execute({query}) {
      const terms = String(query).toLowerCase().split(/\s+/).filter(Boolean);
      const results = (await loadIndex()).filter(({title, url, description}) => {
        const haystack = `${title} ${decodeURIComponent(url)} ${description}`.toLowerCase();
        return terms.every((term) => haystack.includes(term));
      });
      return asText(results.length ? results.slice(0, 25) : 'No matches. Try fewer or broader keywords.');
    },
  },
  {
    name: 'get_crisis_resource',
    description:
      'Fetch a directory page as Markdown (contact numbers, hours, eligibility, sources). Accepts a URL or path returned by search_crisis_resources.',
    inputSchema: {
      type: 'object',
      properties: {url: {type: 'string', description: 'Page URL or path, e.g. /canada-nationwide/kids-help-phone'}},
      required: ['url'],
    },
    async execute({url}) {
      const target = new URL(url, window.location.origin);
      if (target.origin !== window.location.origin) {
        return asText('Only pages on this site can be fetched.');
      }
      const path = target.pathname.replace(/\/$/, '') || '/index';
      const res = await fetch(path.endsWith('.md') ? path : `${path}.md`);
      return asText(res.ok ? await res.text() : `Page not found: ${target.pathname}`);
    },
  },
];

if (ExecutionEnvironment.canUseDOM) {
  const modelContext = document.modelContext || navigator.modelContext;
  if (modelContext?.registerTool) {
    for (const tool of tools) {
      Promise.resolve(modelContext.registerTool(tool)).catch(() => {});
    }
  }
}
